  window.MobilvendorWidgetLoaded = true;

  const WEBHOOK_URL = "https://n8n.mobilvendor.com/webhook/1c8d45e7-24a6-4d80-b05f-867c33711988";
  const BOT_IMG = "https://ik.imagekit.io/nm4jeymx5/Asistente-03-Mobilvendor.jpg?updatedAt=1760720233657";
  const widget = document.createElement("div");
  widget.id = "mv-widget";
  widget.innerHTML = `
    <img id="mv-bot" src="${BOT_IMG}" alt="Asesor Mobilvendor"/>
    <div id="mv-chatbox" style="display:none; flex-direction:column;">
      <div id="mv-header">
        <div class="mv-header-top">
          <img src="${BOT_IMG}" alt="ZEI Bot" class="mv-avatar"/>
          <span class="mv-title">Asesor Comercial Mobilvendor</span>
