        <input id="mv-input" type="text" placeholder="Escribe tu mensaje..." autocomplete="off"/>
        <button id="mv-send" title="Enviar">
          <svg width="24" height="24" fill="#fff" viewBox="0 0 24 24"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"></path></svg>
        </button>
      </div>
    </div>
  `;
  document.body.appendChild(widget);

  const style = document.createElement("style");
  style.textContent = `
    #mv-widget { position:fixed; bottom:24px; right:24px; z-index:99999; font-family:'Segoe UI',Arial,sans-serif;}

    #mv-bot {
      width:72px;height:72px;border-radius:50%;cursor:pointer;
      box-shadow:0 10px 30px rgba(0,55,255,0.20);
      transition:transform 0.18s ease, box-shadow 0.18s ease;
      border:4px solid #fff;background:#fff;
    }
    #mv-bot:hover { transform:scale(1.07); box-shadow:0 12px 36px rgba(0,55,255,0.28); }

    #mv-chatbox {
      position:fixed; bottom:110px; right:32px; width:380px; background:#fff;
      border-radius:22px;box-shadow:0 10px 50px rgba(0,0,0,0.15);
      flex-direction:column;display:none;overflow:hidden;
    }

    /* Header con degradado azul */
    #mv-header {
      background:linear-gradient(90deg, #0037ff 0%, #063bce 100%);
      padding:12px 14px 0 14px;
    }

    #mv-header .mv-header-top {
      display:flex;align-items:center;gap:10px;
      padding:8px 6px 10px 6px;
    }

    #mv-header .mv-avatar {
      width:26px;height:26px;border-radius:50%;
      border:2px solid rgba(255,255,255,0.75);
      box-shadow:0 0 0 2px rgba(0,0,0,0.08);
      background:#fff;
    }

    /* Título en blanco sobre degradado */
    #mv-header .mv-title {
      color:#ffffff;
      font-weight:700;font-size:16px;letter-spacing:0.3px;
      text-shadow:0 1px 3px rgba(0,0,0,0.25);
    }

    /* Barra indicadora (normal: #0037ff, activo: #002B49) */
    #mv-header-bar {
      height:4px;width:100%;
      background:#0037ff;
      transition:background-color 0.15s ease;
    }
    #mv-header-bar.active {
      background:#002B49;
    }

    #mv-messages {
      max-height:420px;min-height:140px;overflow-y:auto;padding:14px 12px;background:#fafafa;
      display:flex;flex-direction:column;gap:10px;
    }

    /* Scrollbar azul */
    #mv-messages::-webkit-scrollbar { width:8px; }
    #mv-messages::-webkit-scrollbar-track { background:#e9eefc;border-radius:10px; }
    #mv-messages::-webkit-scrollbar-thumb {
      background:#0037ff;border-radius:10px;
    }
    #mv-messages::-webkit-scrollbar-thumb:hover { background:#002B49; }

    .mv-message-container {
      display:flex;
      margin-bottom:2px;
    }
    .mv-message-container.user {
      justify-content:flex-end;
    }
    .mv-message-container.bot {
      justify-content:flex-start;
