    #mv-input {
      flex:1;padding:12px;border:1.5px solid #0037ff;
      border-radius:12px;font-size:15px;outline:none;background:#fff;
      transition:box-shadow 0.15s ease, border-color 0.15s ease;
    }
    #mv-input:focus {
      border-color:#002B49;
      box-shadow:0 0 0 3px rgba(0,43,73,0.18);
    }
    #mv-input:disabled { opacity:0.6;cursor:not-allowed; }

    #mv-send {
      width:44px;height:44px;border:none;border-radius:12px;cursor:pointer;
      background:#0037ff;color:#fff;display:flex;align-items:center;justify-content:center;
      box-shadow:0 2px 8px rgba(0,55,255,0.25);
      transition:transform 0.12s ease, background-color 0.12s ease, box-shadow 0.12s ease;
    }
    #mv-send:hover { transform:translateY(-1px);box-shadow:0 4px 12px rgba(0,55,255,0.35); }
    #mv-send:active { background:#002B49;transform:translateY(0);box-shadow:0 2px 8px rgba(0,43,73,0.35); }
    #mv-send:disabled { opacity:0.6;cursor:not-allowed; }

    @media (max-width: 480px){
      #mv-chatbox{ right:16px; width: calc(100vw - 32px); }
