  `;
  document.head.appendChild(style);

  const bot = widget.querySelector("#mv-bot");
  const chatbox = widget.querySelector("#mv-chatbox");
  const input = widget.querySelector("#mv-input");
  const messages = widget.querySelector("#mv-messages");
  const sendBtn = widget.querySelector("#mv-send");
  const headerBar = widget.querySelector("#mv-header-bar");

  const sessionKey = "zeiSessionId";
  let sessionId = localStorage.getItem(sessionKey);
  if (!sessionId) {
    sessionId = "session_" + Date.now() + "_" + Math.random().toString(36).substring(2, 8);
    localStorage.setItem(sessionKey, sessionId);
  }

  bot.addEventListener("click", () => {
    const showing = chatbox.style.display !== "none";
    chatbox.style.display = showing ? "none" : "flex";
    if (!showing && !chatbox.dataset.greeted) {
      appendMessage("Asesor", "¡Hola! 👋 Soy tu asesor comercial de Mobilvendor. ¿En qué puedo ayudarte hoy?");
      chatbox.dataset.greeted = true;
    }
    if (!showing) input.focus();
  });

  // Barra activa al enfocar input
  input.addEventListener("focus", () => headerBar.classList.add("active"));
  input.addEventListener("blur", () => headerBar.classList.remove("active"));

  function sanitize(text){
    const div = document.createElement("div");
    div.textContent = String(text ?? "");
    return div.innerHTML;
  }

  function sanitizeWithLinks(text){
    // Permite solo etiquetas <a> con href válidos
    const tempDiv = document.createElement("div");
    tempDiv.innerHTML = String(text ?? "");

    // Extraer todos los enlaces válidos
    const links = tempDiv.querySelectorAll("a[href]");
    const linkMap = new Map();

    links.forEach((link, index) => {
      const href = link.getAttribute("href");
      const linkText = link.textContent;
      if (href && href.match(/^https?:\/\//)) {
        const placeholder = `__LINK_${index}__`;
        linkMap.set(placeholder, { href, text: linkText });
        link.replaceWith(placeholder);
      }
    });

    // Sanitizar el texto completo
    let sanitizedText = sanitize(tempDiv.textContent);

    // Restaurar los enlaces
    linkMap.forEach((linkData, placeholder) => {
      const safeHref = sanitize(linkData.href);
      const safeText = sanitize(linkData.text);
      const linkHtml = `<a href="${safeHref}" target="_blank" rel="noopener noreferrer">${safeText}</a>`;
      sanitizedText = sanitizedText.replace(placeholder, linkHtml);
    });

    return sanitizedText;
  }

  function sendMessage() {
    const userMsg = input.value.trim();
    if (!userMsg) return;
    appendMessage("Tú", userMsg, true);
    input.value = ""; 
    input.disabled = true;
    sendBtn.disabled = true;

    fetch(WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sessionId, message: userMsg })
    })
    .then(r => r.json())
    .then(data => {
      let response = "";
      if (Array.isArray(data)) {
        response = data[0]?.output ?? data[0]?.message ?? "";
      } else {
        response = data?.output ?? data?.reply ?? data?.message ?? "";
      }
      if (response) appendMessage("Asesor", response);
      else appendMessage("Asesor", "Recibí la solicitud, pero no llegó contenido para mostrar.");
    })
    .catch(err => {
      console.error(err);
      appendMessage("Asesor", "Lo siento, hubo un error al procesar tu mensaje. Por favor intenta nuevamente.");
    })
    .finally(()=>{ 
      input.disabled = false;
      sendBtn.disabled = false;
      input.focus(); 
    });
  }

  input.addEventListener("keypress", e => { if (e.key === "Enter") sendMessage(); });
  sendBtn.addEventListener("click", sendMessage);

  function appendMessage(sender, text, isUser = false) {
    const container = document.createElement("div");
    container.className = `mv-message-container ${isUser ? 'user' : 'bot'}`;

    const now = new Date();
    const time = now.getHours().toString().padStart(2, '0') + ':' + 
                 now.getMinutes().toString().padStart(2, '0');

    const sanitizedSender = sanitize(sender);
    const sanitizedText = isUser ? sanitize(text) : sanitizeWithLinks(text);

    container.innerHTML = `
      <div class="mv-message">
        <span class="mv-message-sender">${sanitizedSender}</span>
        <div class="mv-message-text">${sanitizedText}</div>
        <span class="mv-message-time">${time}</span>
      </div>
    `;

    messages.appendChild(container);
    messages.scrollTop = messages.scrollHeight;
  }
})();

