// ==============================================================
// NODO CODE: Generar Recomendación (Módulos + Producto) al final
// ==============================================================

// Obtener datos del lead desde el nodo anterior (IF)
const outputOriginal = $('If').first().json.output || '';
const sector = $input.first().json.industria || '';
const empleados = $input.first().json.empleados || '';

// Extraer facturación del campo comments usando regex
const commentsText = $input.first().json.comments || '';
const facturacionMatch = commentsText.match(/Rango de facturación:\s*([^\n\r]+)/i);
const facturacion = facturacionMatch ? facturacionMatch[1].trim() : '';

const nombre = $input.first().json.nombre || '';
const primerNombre = (String(nombre).trim().split(/\s+/)[0]) || '';

// --------------------------------------------------------------
// Helpers
// --------------------------------------------------------------
function normalizeText(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

// Función para determinar el tamaño de la empresa
function determinarTamano(empleados, facturacion) {
  const factNorm = normalizeText(facturacion);

  // Empresa PEQUEÑA: 1-4 empleados Y (no factura O menos de $100k)
  const esPequena =
    empleados === "De 1 a 4" &&
    (
      // Variantes comunes de "no factura"
      factNorm.includes("aun no factura") ||
      factNorm.includes("aun no facturo") ||
      factNorm.includes("aun no facturan") ||
      factNorm.includes("todavia no factura") ||
      factNorm.includes("todavia no facturo") ||
      factNorm.includes("no factura") ||
      factNorm.includes("no facturo") ||
      factNorm.includes("sin facturacion") ||
      factNorm.includes("sin facturar") ||
      // Variantes de < 100k
      factNorm.includes("menos de $100.000") ||
      factNorm.includes("menos de $100,000") ||
      factNorm.includes("menos de 100000") ||
      factNorm.includes("menos de 100.000")
    );

  // Empresa GRANDE: 20+ empleados O facturación >= $500k
  const esGrande =
    empleados === "Más de 20" ||
    factNorm.includes("de $500.000 a $2 millones") ||
    factNorm.includes("de $500,000 a $2 millones") ||
    factNorm.includes("mas de $2 millones") ||
    factNorm.includes("mas de $2,000,000") ||
    factNorm.includes("más de $2 millones") ||
    factNorm.includes("más de $2,000,000");

  if (esPequena) return { tipo: "pequeña", label: "Pequeña" };
  if (esGrande) return { tipo: "grande", label: "Grande" };
  return { tipo: "mediana", label: "Mediana" };
}

// Normalizar sector para matching
function normalizarSector(sector) {
  const sectorLower = normalizeText(sector);

  if (sectorLower.includes('consumo') || sectorLower.includes('masivo')) return "Consumo masivo";
  if (sectorLower.includes('ferret')) return "Ferreteria";
  if (sectorLower.includes('farmac') || sectorLower.includes('veterinar')) return "Farmaceutica";
  if (sectorLower.includes('automotriz') || sectorLower.includes('automotor')) return "Automotriz";

  return "Otro";
}

// --------------------------------------------------------------
// Mapeo de recomendaciones por industria y tamaño (tu bloque igual)
// --------------------------------------------------------------
const recomendaciones = {
  "Consumo masivo": {
    "pequeña": {
      modulos: "Comercial, Logística y Facturación Electrónica",
      beneficio: "ideales para mantener control comercial y logístico integral sin necesidad de contabilidad formal",
      caso: "Distribuidores similares lograron implementar ventas móviles y gestión de rutas básica desde el primer mes"
    },
    "mediana": {
      modulos: "Comercial, Logística, Facturación Electrónica y Contabilidad",
      beneficio: "que te permitirán tener operaciones formales con trazabilidad financiera completa",
      caso: "Empresas como la tuya escalaron operaciones con 100+ vendedores sin perder control y mejoraron visibilidad de cobranzas"
    },
    "grande": {
      modulos: "Comercial, Logística, Facturación Electrónica, Contabilidad y Reportería Analítica",
      beneficio: "lo cual te brindará gestión centralizada de múltiples sucursales con dashboards y KPIs para decisiones estratégicas",
      caso: "Distribuidores grandes incrementaron su portafolio +50% (de 1000 a 2000 ítems) y abrieron nuevas líneas en solo 7 meses, migrando a la nube"
    }
  },
  "Ferreteria": {
    "pequeña": {
      modulos: "Comercial, Inventarios y Facturación Electrónica",
      beneficio: "para control de stock en tiempo real y ventas rápidas en caja o ruta",
      caso: "Ferreterías locales digitalizaron su catálogo y automatizaron facturación, reduciendo errores en caja"
    },
    "mediana": {
      modulos: "Comercial, Logístico, Inventarios/WMS y Facturación Electrónica",
      beneficio: "que te darán trazabilidad por lote, control de entregas y optimización de bodegas",
      caso: "Distribuidores ferreteros con 1,500+ SKUs mejoraron control de entregas y redujeron quiebres de stock con WMS"
    },
    "grande": {
      modulos: "Comercial, Logístico, WMS, Facturación Electrónica y Contabilidad",
      beneficio: "para visibilidad total del inventario, márgenes de rentabilidad y gestión de múltiples bodegas",
      caso: "Distribuidores nacionales lograron 100% precisión en entregas, optimizaron márgenes y redujeron costos logísticos"
    }
  },
  "Farmaceutica": {
    "pequeña": {
      modulos: "Comercial con control de lotes",
      beneficio: "para trazabilidad por lote y gestión básica de visitas médicas",
      caso: "Microempresas veterinarias implementaron control de lotes para cumplir con trazabilidad regulatoria"
    },
    "mediana": {
      modulos: "Comercial y Merchandising",
      beneficio: "que te permitirán controlar rutas de visita médica con encuestas y evidencia fotográfica geolocalizada",
      caso: "Distribuidores veterinarios implementaron rutas con GPS para registro de clínicas y médicos con reportes exportables"
    },
    "grande": {
      modulos: "Comercial, Merchandising y Logística",
      beneficio: "para control total de inventario por lote y vendedor, con reportería de visitas médicas y material POP",
      caso: "Empresas veterinarias medianas lograron control total de visitas en tiempo real con validación fotográfica y reportes para auditorías"
    }
  },
  "Automotriz": {
    "pequeña": {
      modulos: "Comercial y Facturación Electrónica",
      beneficio: "con catálogo digital ideal para manejar miles de SKUs",
      caso: "Distribuidores de repuestos digitalizaron catálogos complejos para acelerar búsquedas y cotizaciones en segundos"
    },
    "mediana": {
      modulos: "Comercial, Logístico y Facturación Electrónica",
      beneficio: "para entregas georreferenciadas y trazabilidad de productos de alta rotación",
      caso: "Distribuidores de lubricantes y llantas mejoraron seguimiento de entregas y control de productos por ciudad"
    },
    "grande": {
      modulos: "Comercial, Logístico, WMS, Facturación Electrónica y Contabilidad",
      beneficio: "lo cual te brindará control inteligente de bodegas y trazabilidad completa por SKU y rotación por ciudad",
      caso: "Distribuidores automotrices nacionales lograron trazabilidad completa por producto y cliente, reduciendo quiebres de stock drásticamente"
    }
  },
  "Otro": {
    "pequeña": {
      modulos: "Comercial y Facturación Electrónica",
      beneficio: "para digitalización de ventas desde app móvil con catálogo digital",
      caso: "Empresas diversas digitalizaron su operación comercial desde app móvil en pocas semanas"
    },
    "mediana": {
      modulos: "Comercial, Logístico y Facturación Electrónica",
      beneficio: "para control de pedidos y entregas con integración a tu sistema ERP actual",
      caso: "Empresas con ERPs internos extendieron capacidades al canal móvil sin cambiar su sistema actual"
    },
    "grande": {
      modulos: "Comercial, Logístico, Facturación Electrónica con integración ERP",
      beneficio: "para trazabilidad completa desde la venta hasta la facturación con visibilidad centralizada",
      caso: "Compañías con sistemas propios lograron operación móvil integrada sin interrupciones operativas"
    }
  }
};

// --------------------------------------------------------------
// 1) Recomendación de MÓDULOS (igual, pero la pondremos al final)
// --------------------------------------------------------------
const sectorNormalizado = normalizarSector(sector);
const tamano = determinarTamano(empleados, facturacion);
const recomendacion = recomendaciones[sectorNormalizado][tamano.tipo];

const mensajeRecomendacionModulos =
  `Según el perfil de tu empresa ${tamano.tipo} en ${sector}, ` +
  `los módulos más adecuados para tu operación son: <strong>${recomendacion.modulos}</strong>, ` +
  `${recomendacion.beneficio}. ${recomendacion.caso}.`;

// --------------------------------------------------------------
// 2) Recomendación AUTOMÁTICA DE PRODUCTO (One vs Suite) al final
// --------------------------------------------------------------
const factNorm = normalizeText(facturacion);

const esOne =
  empleados === "De 1 a 4" &&
  (
    factNorm.includes("aun no factura") ||
    factNorm.includes("aun no facturo") ||
    factNorm.includes("todavia no factura") ||
    factNorm.includes("todavia no facturo") ||
    factNorm.includes("no factura") ||
    factNorm.includes("no facturo") ||
    factNorm.includes("sin facturacion") ||
    factNorm.includes("sin facturar") ||
    factNorm.includes("menos de $100.000") ||
    factNorm.includes("menos de $100,000") ||
    factNorm.includes("menos de 100000") ||
    factNorm.includes("menos de 100.000")
  );

const mensajeProducto = esOne
  ? `Te recomiendo revisar <a href="https://mobilvendor.com/mobilvendor-one" target="_blank">Mobilvendor One</a>, una solución ligera ideal para negocios pequeños.`
  : `Te recomiendo que visites <a href="https://mobilvendor.com/mobilvendor-suite" target="_blank">Mobilvendor Suite</a>, una plataforma completa ideal para empresas en crecimiento.`;

// --------------------------------------------------------------
// 3) Construir salida FINAL: outputOriginal + módulos + producto
//    (todo al final, como pediste)
// --------------------------------------------------------------
const outputModificado = [
  String(outputOriginal || '').trim(),
  mensajeRecomendacionModulos,
  mensajeProducto
].filter(Boolean).join('\n\n');

// Retornar datos enriquecidos con el output modificado
return {
  ...($input.first().json),
  output: outputModificado,

  // Campos útiles
  primer_nombre: primerNombre,

  recomendacion_modulos: recomendacion.modulos,
  recomendacion_beneficio: recomendacion.beneficio,
  recomendacion_caso: recomendacion.caso,

  producto_recomendado: esOne ? "Mobilvendor One" : "Mobilvendor Suite",
  tamano_empresa: tamano.label,
  sector_normalizado: sectorNormalizado,
  facturacion_extraida: facturacion
};
